import XCTest
@testable import GJournal

/// Validates the Swift Vietoris–Rips persistent-homology pipeline (β0 union-find + β1
/// Z/2 boundary-matrix reduction) against ripser reference diagrams.
///
/// Reference values generated by `training/ph_oracle.py` (ripser 0.6.x). The fixtures use
/// identical hard-coded coordinates here and in the oracle, so the Swift-computed Euclidean
/// distance matrix and resulting persistence bars must match ripser within 1e-4.
final class PersistentHomologyTests: XCTestCase {

    private let tol = 1e-4

    private func assertClose(_ a: [Double], _ b: [Double],
                             file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(a.count, b.count, "count mismatch: \(a) vs \(b)", file: file, line: line)
        for (x, y) in zip(a, b) {
            XCTAssertEqual(x, y, accuracy: tol, file: file, line: line)
        }
    }

    // MARK: - Fixtures (identical coordinates to training/ph_oracle.py)

    private let twoPoints: [[Double]] = [[0, 0], [3, 0]]
    private let triangle: [[Double]] = [[0, 0], [1, 0], [0.5, 0.8660254]]
    private let square: [[Double]] = [[0, 0], [1, 0], [1, 1], [0, 1]]
    private var octagon: [[Double]] {
        (0..<8).map { k in
            let a = 2 * Double.pi * Double(k) / 8
            return [Foundation.cos(a), Foundation.sin(a)]
        }
    }

    // MARK: - Helpers

    private func h1Bars(_ points: [[Double]], maxEpsilon: Double = .infinity) -> [PersistenceBar] {
        let dm = PersistentHomology.euclideanDistanceMatrix(points)
        return PersistentHomology.vietorisRips(distanceMatrix: dm, maxEpsilon: maxEpsilon)
            .filter { $0.dimension == 1 && $0.death.isFinite }
            .sorted { ($0.death - $0.birth) > ($1.death - $1.birth) }
    }

    private func h0FiniteDeaths(_ points: [[Double]]) -> [Double] {
        let dm = PersistentHomology.euclideanDistanceMatrix(points)
        return PersistentHomology.vietorisRips(distanceMatrix: dm)
            .filter { $0.dimension == 0 && $0.death.isFinite }
            .map { $0.death }
            .sorted()
    }

    private func h0InfiniteCount(_ points: [[Double]]) -> Int {
        let dm = PersistentHomology.euclideanDistanceMatrix(points)
        return PersistentHomology.vietorisRips(distanceMatrix: dm)
            .filter { $0.dimension == 0 && !$0.death.isFinite }
            .count
    }

    // MARK: - Distance matrix

    func testEuclideanDistanceMatrix() {
        let dm = PersistentHomology.euclideanDistanceMatrix(twoPoints)
        XCTAssertEqual(dm[0][1], 3.0, accuracy: tol)
        XCTAssertEqual(dm[1][0], 3.0, accuracy: tol)
        XCTAssertEqual(dm[0][0], 0.0, accuracy: tol)
    }

    // MARK: - β0 (connected components)

    func testTwoPointsH0() {
        // one component survives to infinity, the other dies when the two points merge at d=3
        XCTAssertEqual(h0InfiniteCount(twoPoints), 1)
        assertClose(h0FiniteDeaths(twoPoints), [3.0])
    }

    func testTwoPointsHaveNoLoop() {
        XCTAssertTrue(h1Bars(twoPoints).isEmpty)
    }

    func testTriangleH0() {
        // equilateral triangle side 1: 3 comps -> 1, two finite deaths at 1.0
        XCTAssertEqual(h0InfiniteCount(triangle), 1)
        assertClose(h0FiniteDeaths(triangle), [1.0, 1.0])
    }

    func testTriangleHasNoPersistentLoop() {
        // equilateral: loop is born and immediately filled at the same scale -> no finite bar
        XCTAssertTrue(h1Bars(triangle).isEmpty)
    }

    // MARK: - β1 (loops)

    func testSquareHasOneLoop() {
        let bars = h1Bars(square)
        XCTAssertEqual(bars.count, 1, "unit square must have exactly one H1 loop")
        XCTAssertEqual(bars[0].birth, 1.0, accuracy: tol)
        XCTAssertEqual(bars[0].death, 2.0.squareRoot(), accuracy: tol) // sqrt(2)
    }

    func testSquareH0() {
        XCTAssertEqual(h0InfiniteCount(square), 1)
        assertClose(h0FiniteDeaths(square), [1.0, 1.0, 1.0])
    }

    func testOctagonHasOneProminentLoop() {
        let bars = h1Bars(octagon)
        XCTAssertGreaterThanOrEqual(bars.count, 1, "circle-like octagon must have a loop")
        // ripser: birth = 2*sin(pi/8) = 0.765367, death = 1.847759
        XCTAssertEqual(bars[0].birth, 0.765367, accuracy: tol)
        XCTAssertEqual(bars[0].death, 1.847759, accuracy: tol)
    }

    func testLoopPersistenceMetric() {
        // square: single loop [1, sqrt(2)) -> LP = sqrt(2) - 1
        let dm = PersistentHomology.euclideanDistanceMatrix(square)
        let bars = PersistentHomology.vietorisRips(distanceMatrix: dm)
        let lp = PersistentHomology.loopPersistence(bars)
        XCTAssertEqual(lp, 2.0.squareRoot() - 1.0, accuracy: tol)
    }

    // MARK: - Edge cases

    func testSinglePointHasOneInfiniteComponent() {
        let dm = PersistentHomology.euclideanDistanceMatrix([[0.0, 0.0]])
        let bars = PersistentHomology.vietorisRips(distanceMatrix: dm)
        XCTAssertEqual(bars.filter { $0.dimension == 0 && !$0.death.isFinite }.count, 1)
        XCTAssertTrue(bars.allSatisfy { $0.dimension == 0 })
    }

    func testEmptyInput() {
        let bars = PersistentHomology.vietorisRips(distanceMatrix: [])
        XCTAssertTrue(bars.isEmpty)
    }

    func testMaxEpsilonPrunesTheSquareLoop() {
        // with epsilon capped below the diagonal (sqrt(2)), the loop never dies -> becomes
        // an essential (infinite) H1 class, so there is no *finite* H1 bar
        let bars = h1Bars(square, maxEpsilon: 1.2)
        XCTAssertTrue(bars.isEmpty)
    }
}
